function fmt(d) {
  if (IsEmpty(d)) { return ''; }
  var t = TypeOf(d);
  if (t == 'Date') { return Text(ToUTC(d), 'MMMM D, Y'); }
  if (t == 'DateOnly') { return Text(d, 'MMMM D, Y'); }
  var p = Split(d, '-');
  var m = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  return m[Number(p[1]) - 1] + ' ' + Text(Number(p[2])) + ', ' + p[0];
}
function monthOf(d) {
  var s = fmt(d); var parts = Split(s, ' ');
  return parts[0] + ' ' + parts[2];
}
var a = $feature.StartDate; var b = $feature.EndDate;
if ($feature.DatePrecision == 'month') { var ma = monthOf(a); var mb = monthOf(b); return IIf(ma == mb, ma, ma + ' to ' + mb); }
if ($feature.DatePrecision == 'approximate') { return 'About ' + fmt(a) + ' to ' + fmt(b); }
var fa = fmt(a); var fb = fmt(b);
return IIf(fa == fb, fa, fa + ' to ' + fb);

